-- ============================================================
-- 近代建築（テーマID: 20, category_id: 5）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(5, 20, '京都市上京区に位置する「京都府庁旧本館」の建築様式として正しいのはどれか。', 'ゴシック様式', 'ルネサンス様式', 'バロック様式', '和洋折衷様式', 1, '京都府庁旧本館（1904年竣工）は、ルネサンス様式を基調とした明治期を代表する官庁建築です。現在も執務室として使用されており、現役最古の官公庁舎として国の重要文化財に指定されています。', 1, false),
(5, 20, '1895年に竣工した「京都国立博物館（旧帝国京都博物館）本館」を設計した建築家はだれか。', '辰野金吾', '片山東熊', '伊東忠太', '武田五一', 1, '京都国立博物館（現・明治古都館）は宮廷建築家の片山東熊（かたやまとうくま、1854〜1917年）が設計しました。フランス・バロック様式を取り入れた優美な外観が特徴で、国の重要文化財です。', 1, false),
(5, 20, '「旧日本銀行京都支店（現・京都文化博物館別館）」を設計した建築家はだれか。', '片山東熊', '辰野金吾', '伊東忠太', '中村達太郎', 1, '旧日本銀行京都支店（1906年竣工）は辰野金吾（たつのきんご、1854〜1919年）が設計しました。東京駅など多くの重要建築を手がけた明治の代表的建築家です。レンガ造りの重厚な外観が特徴で国の重要文化財です。', 1, false),
(5, 20, '同志社大学のアーモスト館・ハリス理化学館など多くの建物が国の重要文化財に指定されているが、同志社のキャンパスがある京都の地はどこか。', '烏丸御池', '今出川・相国寺周辺', '左京区岡崎', '東山区', 1, '同志社大学は京都市上京区、今出川通と相国寺の北側に位置しています。明治期に建てられたレンガ造りの建物群が多数残り、キャンパス全体が歴史的景観を形成しています。', 1, false),
(5, 20, '「平安神宮」の建立年として正しいのはどれか。', '1893年（明治26年）', '1895年（明治28年）', '1900年（明治33年）', '1910年（明治43年）', 1, '平安神宮は1895年（明治28年）、平安遷都1100年を記念して建立されました。平安京の大内裏（朝堂院）を約8分の5スケールで復元した朱塗りの建物群が特徴です。', 1, false),
(5, 20, '「京都市美術館（現・京都市京セラ美術館）」の竣工年として正しいのはどれか。', '1928年', '1933年', '1940年', '1952年', 1, '京都市美術館（現・京都市京セラ美術館）は1933年（昭和8年）に竣工し、公立美術館として日本最古の部類に入ります。帝冠様式（日本の伝統的屋根＋西洋建築）を取り入れた昭和初期を代表する建築です。', 2, false),
(5, 20, '「京都国際会館」を設計した建築家はだれか。', '丹下健三', '黒川紀章', '大谷幸夫', '安藤忠雄', 2, '京都国際会館（1966年竣工）は大谷幸夫（おおたによしお、1924〜2013年）が設計しました。逆台形を重ねたコンクリートの外観が特徴的で、日本における近代建築の代表作のひとつです。', 2, false),
(5, 20, '「旧京都中央電話局（現・新風館）」の保存・再活用が注目された建築の様式はどれか。', '明治期のレンガ造り', '大正・昭和初期のモダニズム建築', '江戸時代の木造建築', '戦後の復興建築', 1, '旧京都中央電話局（1926年竣工）は大正・昭和初期のモダニズム建築で、吉田鉄郎（よしだてつろう）設計の歴史的建造物です。現在は「新風館」として商業施設に再活用されており、歴史的建物の保存活用の事例として知られます。', 2, false),
(5, 20, '京都市内に残る「レトロ建築」として有名な「旧武徳殿（ぶとくでん）」はどこに位置するか。', '二条城内', '岡崎公園内', '金閣寺参道', '伏見桃山城跡', 1, '旧武徳殿は京都市左京区岡崎の平安神宮前（岡崎公園内）に位置します。1899年（明治32年）建設の武道練習場で、現在も武道の稽古場として使用されています。国の重要文化財に指定されています。', 2, false),
(5, 20, '京都の近代建築で「帝冠様式（ていかんようしき）」の特徴を表すのはどれか。', '西洋建築に日本の伝統的な屋根を乗せた建築様式', '完全に西洋建築の様式で建てられた建築', '江戸時代の建築様式をそのまま継承した建築', 'コンクリート打ちっぱなしの現代建築', 0, '帝冠様式は昭和初期に流行した建築様式で、鉄筋コンクリートの西洋建築に日本の伝統的な瓦屋根を組み合わせたものです。国家主義的な思潮の中で「和洋折衷」を実現しようとした様式で、京都市美術館がその代表例です。', 2, false),
(5, 20, '京都の「一條戻橋（もどりばし）」や「夷川ダム」など近代土木遺産を多く残す施設として知られるものはどれか。', '京都府庁', '琵琶湖疏水・岡崎疏水', '京都市水道局', '嵐山発電所', 1, '明治時代に建設された琵琶湖疏水（びわこそすい）は、大津から京都へ水を引いた大規模な土木事業で、蹴上インクラインや蹴上発電所など多くの近代土木遺産が残っています。', 2, false),
(5, 20, '「蹴上インクライン（けあげいんくらいん）」とはどのような施設か。', '急な坂を上るためのエスカレーター', '琵琶湖疏水で船を陸上輸送するための傾斜鉄道', '京都市電の急勾配区間', '電気を起こすための水力発電設備', 1, '蹴上インクラインは琵琶湖疏水の水位差を乗り越えるため、船を台車に乗せてレールで上下させた傾斜鉄道（インクライン）の跡地です。現在は廃線になり、線路と桜並木の景観で知られる近代遺産として親しまれています。', 1, false),
(5, 20, '「旧京都市立芸術大学（京都市立美術工芸学校跡）」はどの地区に位置していたか。', '上京区今出川', '西京区大枝沓掛', '左京区岡崎', '中京区西ノ京', 1, '旧京都市立芸術大学キャンパスは長年、西京区大枝沓掛に位置していましたが、2023年に京都駅東部の崇仁地区（下京区）へ移転しました。', 2, false),
(5, 20, '「東華菜館（とうかさいかん）」として現在も使われている建物は、もともとは何として建てられたか。', '料亭', 'レストラン（洋食レストラン）', '銀行', '商社の社屋', 1, '東華菜館（四条大橋西詰）は1926年（大正15年）、ウィリアム・メレル・ヴォーリズ設計のスペイン風建築として竣工しました。もともとはレストラン（料理店）として建てられ、現在も中国料理店として営業しています。', 3, false),
(5, 20, '京都の近代建築において「ヴォーリズ建築」として知られる建築家の出身国はどこか。', 'イギリス', 'ドイツ', 'アメリカ', 'フランス', 2, 'ウィリアム・メレル・ヴォーリズ（William Merrell Vories、1880〜1964年）はアメリカ出身の建築家・実業家・宣教師です。関西を中心に多くのキリスト教関連施設や教育機関を設計し、「ヴォーリズ建築」として知られています。', 2, false),
(5, 20, '「京都市役所本庁舎」の建築様式として正しいのはどれか。', '純粋な西洋様式', '帝冠様式', '和風建築', 'ガラス張りのモダニズム', 1, '京都市役所本庁舎（1931年竣工）は帝冠様式を採用しており、鉄筋コンクリート造の建物に日本瓦の屋根を組み合わせた外観が特徴です。国の登録有形文化財に登録されています。', 2, false),
(5, 20, '「京都工芸繊維大学（きょうとこうげいせんいだいがく）」のキャンパスがある場所はどこか。', '右京区西院', '左京区松ヶ崎', '上京区今出川', '中京区西ノ京', 1, '京都工芸繊維大学は京都市左京区松ヶ崎（まつがさき）にキャンパスがあります。蚕業・染色などの伝統産業から発展した大学で、現在もデザイン・建築・工学などの専門教育機関として知られています。', 3, false),
(5, 20, '平安神宮の「應天門（おうてんもん）」は平安京の正門を何分の何スケールで復元したものか。', '実物大', '2分の1', '8分の5', '3分の2', 2, '平安神宮は平安京の大内裏（朝堂院）の主要建物を約8分の5（実物の約62.5%）スケールで復元しています。應天門・太極殿（外拝殿）・廻廊など赤・白の鮮やかな建物群が並んでいます。', 3, false),
(5, 20, '明治期に建てられた「南禅寺の水路閣（すいろかく）」の素材として正しいのはどれか。', '木造', 'レンガ造り', '石造', 'コンクリート造', 1, '南禅寺境内を流れる「水路閣（すいろかく）」は1888年（明治21年）に建設された琵琶湖疏水の水路橋（アーチ橋）で、レンガ造りです。南禅寺の境内という異色の場所に建つため、当初は景観問題となりましたが、現在は観光名所として親しまれています。', 1, false),
(5, 20, '京都の近代建築保存を目的として京都市が定めた条例はどれか。', '京都市伝統建築保存条例', '京都市歴史的建築物の保全及び活用に関する条例', '京都市近代建築文化財条例', '京都市景観保護条例', 1, '「京都市歴史的建築物の保全及び活用に関する条例」（2016年施行）は、市内の歴史的建築物を登録・認定し、保全と活用を推進するための条例です。近代建築も含む多様な建物の保存に役立てられています。', 3, false);

